SELECT role
FROM event_users
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND user_id = #{userId}

SELECT eu.event_id,
       eu.role = #{ownerRole} AS owner,
       (SELECT count(*) FROM event_users o
         WHERE o.event_id = eu.event_id AND o.role = #{ownerRole} AND o.user_id <> eu.user_id
           AND NOT

       ) AS other_owners,
       EXISTS (
         SELECT 1 FROM owner_transfers t
         WHERE t.event_id = eu.event_id AND t.from_user_id = eu.user_id
           AND t.status = #{handoverStatus}
       ) AS handover_accepted,
       (SELECT count(*) FROM tasks tk
         WHERE tk.event_id = eu.event_id AND tk.assignee_user_id = eu.user_id
           AND tk.status IN

             #{status}

       ) AS open_tasks
FROM event_users eu
WHERE eu.space_id = #{spaceId} AND eu.user_id = #{userId}

